builder.Services.AddOutputCache(options =>
{
    options.AddPolicy("ProductList", policy =>
    {
        policy.Expire(TimeSpan.FromMinutes(5))
              .SetVaryByQuery("category", "page")
              .SetLocking(OutputCacheLocking.AllowLocking);
    });

    options.AddBasePolicy(policy =>
    {
        policy.With(p => p.CacheKeyGenerator = context =>
        {
            // Include the user's role in the cache key for role-specific content
            var role = context.HttpContext.User.FindFirst("role")?.Value;
            return $"{context.HttpContext.Request.Path}:{role}";
        });
    });
});

var app = builder.Build();
app.UseOutputCache(); // After routing, before auth

// Minimal API endpoint
app.MapGet("/api/products", async (ProductService service) =>
{
    var products = await service.GetAllAsync();
    return Results.Ok(products);
})
.CacheOutput("ProductList"); // Uses the policy defined above

// Controller endpoint
[HttpGet("api/products/{id}")]
[OutputCache(PolicyName = "ProductDetail")]
public async Task<ActionResult<ProductDto>> GetProduct(int id)
{
    var product = await _service.GetByIdAsync(id);
    if (product is null) return NotFound();
    return Ok(product);
}

public class ProductController : ControllerBase
{
    private readonly IOutputCacheEntryEvictor _evictor;

    [HttpPut("api/products/{id}")]
    public async Task<IActionResult> UpdateProduct(int id, UpdateProductDto dto)
    {
        await _service.UpdateAsync(id, dto);

        // Invalidate all cached product pages
        await _evictor.EvictByTagAsync("products");

        return NoContent();
    }
}
